-- DMF0020 Sales Price measure 메타 (handleInsert 의 동적 measure source)
MERGE INTO SCM_MST_SHEET_MEASURE t USING (SELECT 'DMF0020' PROGRAM_ID, 'Sales Price' SHEET_NAME, 'RTF_SYS_RP' COLUMN_NAME FROM DUAL) s
   ON (t.PROGRAM_ID=s.PROGRAM_ID AND t.SHEET_NAME=s.SHEET_NAME AND t.COLUMN_NAME=s.COLUMN_NAME)
 WHEN MATCHED THEN UPDATE SET COLUMN_LABEL_NAME='RTF', SORT_ORDER_NO=1, VALID_YN='Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
 WHEN NOT MATCHED THEN INSERT (PROGRAM_ID, SHEET_NAME, COLUMN_NAME, COLUMN_LABEL_NAME, SORT_ORDER_NO, VALID_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
   VALUES ('DMF0020','Sales Price','RTF_SYS_RP','RTF',1,'Y','admin',SYSDATE,'admin',SYSDATE);
MERGE INTO SCM_MST_SHEET_MEASURE t USING (SELECT 'DMF0020' PROGRAM_ID, 'Sales Price' SHEET_NAME, 'KRW' COLUMN_NAME FROM DUAL) s
   ON (t.PROGRAM_ID=s.PROGRAM_ID AND t.SHEET_NAME=s.SHEET_NAME AND t.COLUMN_NAME=s.COLUMN_NAME)
 WHEN MATCHED THEN UPDATE SET COLUMN_LABEL_NAME='KRW', SORT_ORDER_NO=2, VALID_YN='Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
 WHEN NOT MATCHED THEN INSERT (PROGRAM_ID, SHEET_NAME, COLUMN_NAME, COLUMN_LABEL_NAME, SORT_ORDER_NO, VALID_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
   VALUES ('DMF0020','Sales Price','KRW','KRW',2,'Y','admin',SYSDATE,'admin',SYSDATE);
MERGE INTO SCM_MST_SHEET_MEASURE t USING (SELECT 'DMF0020' PROGRAM_ID, 'Sales Price' SHEET_NAME, 'USD' COLUMN_NAME FROM DUAL) s
   ON (t.PROGRAM_ID=s.PROGRAM_ID AND t.SHEET_NAME=s.SHEET_NAME AND t.COLUMN_NAME=s.COLUMN_NAME)
 WHEN MATCHED THEN UPDATE SET COLUMN_LABEL_NAME='USD', SORT_ORDER_NO=3, VALID_YN='Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
 WHEN NOT MATCHED THEN INSERT (PROGRAM_ID, SHEET_NAME, COLUMN_NAME, COLUMN_LABEL_NAME, SORT_ORDER_NO, VALID_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
   VALUES ('DMF0020','Sales Price','USD','USD',3,'Y','admin',SYSDATE,'admin',SYSDATE);
MERGE INTO SCM_MST_SHEET_MEASURE t USING (SELECT 'DMF0020' PROGRAM_ID, 'Sales Price' SHEET_NAME, 'LOC' COLUMN_NAME FROM DUAL) s
   ON (t.PROGRAM_ID=s.PROGRAM_ID AND t.SHEET_NAME=s.SHEET_NAME AND t.COLUMN_NAME=s.COLUMN_NAME)
 WHEN MATCHED THEN UPDATE SET COLUMN_LABEL_NAME='LOC', SORT_ORDER_NO=99, VALID_YN='Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
 WHEN NOT MATCHED THEN INSERT (PROGRAM_ID, SHEET_NAME, COLUMN_NAME, COLUMN_LABEL_NAME, SORT_ORDER_NO, VALID_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
   VALUES ('DMF0020','Sales Price','LOC','LOC',99,'Y','admin',SYSDATE,'admin',SYSDATE);
COMMIT;
